Debug a tokenizer that hangs. Save as buggy_tok.py:

DICT = {'ta', 'tana', 'na', 'ka', 'kata'}
MAXLEN = 4

def tokenize(s):
    out = []
    i = 0
    while i < len(s):
        for L in range(MAXLEN, 0, -1):
            piece = s[i:i+L]
            if piece in DICT:
                out.append(piece)
                i += L
                break
        else:
            i += 0  # skip unknown
    return out

